<?php
declare(strict_types=1);
$settings = require dirname(__DIR__) . '/config.php';
if (session_status() !== PHP_SESSION_ACTIVE) {
    session_name('dominion_admin');
    session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off','samesite'=>'Strict','path'=>'/']);
    session_start();
}
function db(): PDO {
    static $pdo = null; global $settings;
    if (!$pdo) $pdo = new PDO($settings['dsn'],$settings['db_user'],$settings['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
    return $pdo;
}
function h(?string $v): string { return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function current_admin(): ?array { return $_SESSION['admin'] ?? null; }
function require_login(): array {
    if (!current_admin()) { header('Location: login.php'); exit; }
    $stmt=db()->prepare('SELECT u.id,u.full_name,u.email,u.is_active,r.id role_id,r.role_key,r.display_name role_name FROM admin_users u JOIN roles r ON r.id=u.role_id WHERE u.id=?');
    $stmt->execute([$_SESSION['admin']['id']]); $fresh=$stmt->fetch();
    if (!$fresh || !(int)$fresh['is_active']) { $_SESSION=[]; session_destroy(); header('Location: login.php'); exit; }
    $p=db()->prepare('SELECT p.permission_key FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE rp.role_id=?');$p->execute([$fresh['role_id']]);
    $fresh['permissions']=array_column($p->fetchAll(),'permission_key'); $_SESSION['admin']=$fresh; return $fresh;
}
function require_permission(string $permission): array {
    $admin=require_login(); if (!in_array($permission,$admin['permissions'],true)) { http_response_code(403); page_start('Access denied',$admin); echo '<section class="box"><h1>Access denied</h1><p>Your assigned role does not include permission for this page.</p></section>'; page_end(); exit; } return $admin;
}
function csrf_token(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function check_csrf(): void { if (!hash_equals(csrf_token(),(string)($_POST['csrf']??''))) { http_response_code(419); exit('This page expired. Refresh and try again.'); } }
function page_start(string $title, ?array $admin=null): void {
    $admin=$admin??current_admin(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> · Dominion Festival Admin</title><style>
