);color:white;text-decoration:none;display:inline-block;padding:9px 13px;font-weight:700;font-size:12px;cursor:pointer}.btn.secondary,button.secondary{background:#eef1f6;color:var(--navy);border:1px solid var(--line)}.btn.danger,button.danger{background:#9e3832}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field label{display:block;font-size:11px;font-weight:700;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d5dbe5;border-radius:7px;font:inherit;background:white}.field textarea{min-height:95px}.field.full{grid-column:1/-1}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.notice{border-radius:8px;background:#edf4fb;color:#435771;padding:11px 13px;font-size:12px;margin:12px 0}.error{color:var(--red);background:#fff0ef;padding:10px;border-radius:7px;margin:12px 0}.success{color:var(--green);background:#e9f6ef;padding:10px;border-radius:7px;margin:12px 0}.detail{display:grid;grid-template-columns:180px 1fr;gap:7px 14px}.detail dt{color:var(--muted);font-size:12px}.detail dd{margin:0;font-size:13px;overflow-wrap:anywhere}.login{max-width:430px;margin:8vh auto;padding:24px;background:#fff;border:1px solid var(--line);border-radius:12px}.login .field{margin:14px 0}.login button{width:100%;padding:12px}.video{margin-top:12px;width:min(100%,700px);background:#111;border-radius:8px}.empty{text-align:center;color:var(--muted);padding:28px}footer{text-align:center;color:#8a93a2;font-size:11px;margin-top:24px}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.bar{align-items:flex-start;flex-direction:column}.detail{grid-template-columns:1fr;gap:2px}.detail dd{margin-bottom:9px}}@media(max-width:540px){.grid,.formgrid{grid-template-columns:1fr}.field.full{grid-column:auto}.container{padding-top:20px}}
</style></head><body><?php if($admin): ?><header class="bar"><div class="brand"><small>RCCG Dominion Centre</small>Festival Admin</div><nav><?php if(in_array('applications.view',$admin['permissions']??[],true)):?><a href="index.php">Applications</a><?php endif?><?php if(in_array('reports.view',$admin['permissions']??[],true)):?><a href="index.php?reports=1">Reports</a><?php endif?><?php if(in_array('roles.manage',$admin['permissions']??[],true)):?><a href="roles.php">Roles & permissions</a><?php endif?><?php if(in_array('admins.manage',$admin['permissions']??[],true)):?><a href="users.php">Admin users</a><?php endif?><a href="logout.php">Sign out</a><span class="who"><?=h($admin['full_name'])?> · <?=h($admin['role_name']??$admin['role_key']??'')?></span></nav></header><?php endif ?><main class="container">
<?php }
function page_end(): void { ?></main><footer>Dominion Festival 3.0 | ARISE · Authorized access only</footer></body></html><?php }
